new_string:
/* Parked parent user context across coop child runs (see yield_to_child).
 * Must NOT share slots with child staging in g_bfree_fork_saved_*: the COOP
 * asm path loads fork_saved_rbx… for whichever side is resuming, which stomped
 * parent rsp/rcx when mixed into the same globals (2nd pipe #GP, RSP≈0x1F8). */
static uint64_t g_coop_parent_rcx, g_coop_parent_r11, g_coop_parent_rsp;
static uint64_t g_coop_parent_rbx, g_coop_parent_rbp, g_coop_parent_r12;
static uint64_t g_coop_parent_r13, g_coop_parent_r14, g_coop_parent_r15, g_coop_parent_rdx;
